import { globalRegistry } from "../../utils/global-registry.js";
const registry = globalRegistry("@mit-sdg/sync-engine/gateway-registry", () => ({
    applicationsByInvoker: new WeakMap(),
    applicationsByGateway: new WeakMap(),
}));
export function rememberApplicationInvoker(invoker, identity, publicInterface) {
    registry.applicationsByInvoker.set(invoker, { identity, publicInterface });
}
export function applicationBehindInvoker(invoker) {
    return registry.applicationsByInvoker.get(invoker);
}
export function rememberGatewayApplication(gateway, application) {
    registry.applicationsByGateway.set(gateway, application);
}
export function applicationBehindGateway(gateway) {
    return registry.applicationsByGateway.get(gateway)?.identity;
}
